type Future[T any] struct {client *Client;id uint64;read func(*Client,uint64)([]T,error);closed bool}
func(value *Future[T]) Receive()(T,bool,error){var zero T;if value==nil||value.closed{return zero,false,ErrClosed};client:=value.client;client.mu.Lock();defer client.mu.Unlock();if client.handle==0{return zero,false,ErrClosed};items,err:=value.read(client,value.id);value.closed=true;runtime.SetFinalizer(value,nil);if err!=nil{return zero,false,err};if len(items)>1{return zero,false,errors.New("future returned more than one value")};if len(items)==0{return zero,false,nil};return items[0],true,nil}
func(value *Future[T]) Close()error{if value==nil||value.closed{return nil};client:=value.client;client.mu.Lock();defer client.mu.Unlock();if client.handle==0{value.closed=true;return nil};err:=client.closeReader(value.id);if err==nil{value.closed=true;runtime.SetFinalizer(value,nil)};return err}
type Stream[T any] struct {client *Client;id uint64;read func(*Client,uint64)([]T,error);closed bool}
func(value *Stream[T]) Next()(T,bool,error){var zero T;if value==nil||value.closed{return zero,false,ErrClosed};client:=value.client;client.mu.Lock();defer client.mu.Unlock();if client.handle==0{return zero,false,ErrClosed};items,err:=value.read(client,value.id);if err!=nil{return zero,false,err};if len(items)>1{return zero,false,errors.New("stream reader returned more than one item")};if len(items)==0{value.closed=true;runtime.SetFinalizer(value,nil);return zero,false,nil};return items[0],true,nil}
func(value *Stream[T]) Close()error{if value==nil||value.closed{return nil};client:=value.client;client.mu.Lock();defer client.mu.Unlock();if client.handle==0{value.closed=true;return nil};err:=client.closeReader(value.id);if err==nil{value.closed=true;runtime.SetFinalizer(value,nil)};return err}
